"use strict";
const _ = require("lodash");
const Resource = require("../tools.js").Resource,
  Librus = require("../api.js");

module.exports = class Info extends Resource {
  /**
   * Get notifications
   * https://synergia.librus.pl/uczen_index
   *
   * @returns {Promise}
   */
  getNotifications() {
    return this.api
      ._mapper("uczen_index", "#graphic-menu ul li", ($, element) => {
        return $(element).text().replace(/\D+/g, "").trim().length
          ? $(element).text().replace(/\D+/g, "").trim()
          : "0";
      })
      .then((array) => {
        return _.zipObject(
          [
            "grades",
            "absence",
            "inbox",
            "announcements",
            "calendar",
            "homework",
          ],
          array.slice(1).map((e) => Number(e))
        );
      });
  }
  getAccountInfo() {
    let parser = ($, element) => {
      return {
        student: {
          nameSurname: $(
            "#body > div > div > table > tbody > tr:nth-child(1) > td"
          ).text(),
          class: $("#body > div > div > table > tbody > tr:nth-child(2) > td")
            .text()
            .trim(),
          index: $("#body > div > div > table > tbody > tr:nth-child(3) > td")
            .text()
            .trim(),
          educator: $(
            "#body > div > div > table > tbody > tr:nth-child(4) > td"
          )
            .text()
            .trim(),
        },
        account: {
          nameSurname: $(
            "#body > div > div > table > tbody > tr:nth-child(7) > td"
          )
            .text()
            .trim(),
          login: $("#body > div > div > table > tbody > tr:nth-child(8) > td")
            .text()
            .trim(),
        },
      };
    };
    return this.api._singleMapper("informacja", "html", parser);
  }

  /**
   * Get grade info
   * https://synergia.librus.pl/przegladaj_oceny/szczegoly
   *
   * @param gradeId Grade ID
   * @returns {Promise}
   */
  getGrade(gradeId) {
    let parser = ($, table) => {
      let keys = [
        "grade",
        "category",
        "date",
        "teacher",
        "lesson",
        "inAverage",
        "multiplier",
        "user",
        "comment",
      ];

      switch ($(table).find("th").length) {
        /** e.g. - */
        case 7:
          _.pullAt(keys, 5, 6);
          break;

        /** with multiplier 0 */
        case 8:
          _.pullAt(keys, 6);
          break;
      }

      let values = Librus.mapTableValues($(table), keys);
      return "inAverage" in values
        ? _.assign(values, {
            inAverage:
              $(table).find("img").attr("src") === "/images/aktywne.png",
          })
        : values;
    };
    return this.api._singleMapper(
      `przegladaj_oceny/szczegoly/${gradeId}`,
      ".container-background table.decorated.medium.center tbody",
      parser
    );
  }
  /**
   * Get Point grade info
   * https://synergia.librus.pl/przegladaj_oceny_punktowe/szczegoly
   *
   * @param gradeId Grade ID
   * @returns {Promise}
   */
  getPointGrade(gradeId) {
    let parser = ($, table) => {
      let keys = [
        "grade",
        "category",
        "date",
        "teacher",
        "lesson",
        "inAverage",
        "multiplier",
        "user",
        "comment",
      ];

      switch ($(table).find("th").length) {
        /** e.g. - */
        case 7:
          _.pullAt(keys, 5, 6);
          break;

        /** with multiplier 0 */
        case 8:
          _.pullAt(keys, 6);
          break;
      }

      let values = Librus.mapTableValues($(table), keys);
      return "inAverage" in values
        ? _.assign(values, {
            inAverage:
              $(table).find("img").attr("src") === "/images/aktywne.png",
          })
        : values;
    };
    return this.api._singleMapper(
      `przegladaj_oceny_punktowe/szczegoly/${gradeId}`,
      ".container-background table.decorated.medium.center",
      parser
    );
  }
  /**
   * Get lucky number
   * https://synergia.librus.pl/uczen/index
   *
   * @returns {Promise}
   */
  getLuckyNumber() {
    let parser = ($, element) => {
      return parseInt(element.children[1].children[0].data);
    };
    return this.api._singleMapper("uczen/index", ".luckyNumber", parser);
  }
  /**
   * Get grades list
   * https://synergia.librus.pl/przegladaj_oceny/uczen
   *
   * @returns {Promise}
   */
  getGrades() {
    let parser = ($, row) => {
      let children = $(row).children("td");

      let average = (colIndex) => {
        return parseFloat($(children[colIndex]).text());
      };

      // Produces a stable positive 31-bit integer from a string.
      // Used for descriptive grades that have no numeric ID in the URL.
      function stableHash(str) {
        let h = 5381;
        for (let i = 0; i < str.length; i++) {
          h = (((h << 5) + h) + str.charCodeAt(i)) & 0x7fffffff;
        }
        return h || 1;
      }

      let semester = (startColumn) => {
        let grades = _.map(
          $(children[startColumn]).find("span.grade-box"),
          (element) => {
            const href = $(element).find("a").attr("href") || '';
            let id;
            if (href && !href.startsWith('javascript:')) {
              id = parseInt(href.split("/")[href.split("/").length - 1]);
            } else {
              id = stableHash($(element).find("a").attr("title") || '');
            }
            return {
              id,
              info: $(element).find("a").attr("title").replace(/<\s*br\s*\/?\s*>/g, "\n"),
              value: $(element).trim(),
            };
          }
        );
        return {
          grades: grades,
          tempAverage: average(startColumn + 1),
          average: average(startColumn + 2),
        };
      };

      const name = $(children[1]).trim();
      if (name) {
        // primary_lower (kl. 1-3): 4 columns — expand | subject | Okres 1 | Okres 2
        // primary_upper / secondary: 10+ columns with separate avg columns per semester
        const isPrimaryLower = children.length <= 5;
        return {
          name,
          semester: isPrimaryLower
            ? [semester(2), semester(3)]
            : [semester(2), semester(5), semester(6), semester(9)],
          tempAverage: isPrimaryLower ? NaN : average(8),
          average: isPrimaryLower ? NaN : average(9),
        };
      }
    };
    return this.api._mapper(
      "przegladaj_oceny/uczen",
      "table.decorated.stretch:eq(1) > tbody > tr[class^='line']:not([name]),table.decorated.stretch:eq(1) > tr[class^='line']:not([name])",
      parser
    );
  }
};
